function generatePrincipal() {
  const chars = "abcdefghijklmnopqrstuvwxyz0123456789";
  const rand = () => Array.from(
    { length: 5 },
    () => chars[Math.floor(Math.random() * chars.length)]
  ).join("");
  return [rand(), rand(), rand(), rand(), rand()].join("-");
}
